select DOCUMENT_ID documentId, DOCUMENT_TYPE_CODE documentType, TO_CHAR(RECIEVE_DT, 'MM/DD/YYYY') recievedDate,PROVIDER_NAME providerName,PROVIDER_ADDRESS providerAddress, ASSOCIATION_DATE associationDate, FIRST_NAME firstName, LAST_NAME lastName, DATE_OF_BIRTH dateOfBirth, DATE_OF_DEATH dateOfDeath, SSN ssn, ETHNICITY ethnicity, RACE race, ADDRESS address, SURV_ASSIGNMENT_ID assignmentId, SURV_STATUS assignmentStatus, SENT_MESSAGE_FLAG sentMessageFlag, RETURN_MESSAGE_FLAG returnMessageFlag, ALT_ACRF_INFO altValues, ASSOCIATION_STATUS_CODE associationStatus, RAS_DOC_ID rasDocId, SIERRA_FLAG sierraFlag, DISCARD_STATUS discardStatus, HL7_EXISTS hl7Exists, nyc_reject_doc_ind nycRejectDocInd, DEMO_DOCUMENT_ID demoDocId, LAFT_FOLLOWUP_EXISTS laftFollowupExists from NYEHMS_DOCUMENT_TIMELINE_VW where STATENO = #{p_stateNo} and doc_type_code IN (SELECT * FROM TABLE(get_user_permissions(#{p_module_id}, #{p_worker_id})))
and doc_type_code = #{p_documentType}
order by RECIEVE_DT desc nulls last

		select std_dth.DOCUMENT_ID documentId,  #{documentType}  as documentType, std_dth.FNAME firstName, std_dth.LNAME lastName, DOB_TEXT  dateOfBirth, DOD_TEXT  dateOfDeath, std_dth.SSN ssn, e.ETHNICITY_DESCRIPTION ethnicity,  
std_dth.PERSON_ADDRESS || ', ' || std_dth.PERSON_CITY || ', ' || std_dth.PERSON_STATE || ', ' || std_dth.PERSON_ZIP address, TO_CHAR(doc_locator.RECEIVED_DATE,'MM/DD/YYYY') recievedDate, DECODE( race_indian , 1 , 'IND/' ,NULL) || DECODE(  race_black , 1 , 'BLK/' ,NULL) || DECODE(  race_asian , 1 , 'ASI/' ,NULL) || DECODE(  race_pacific , 1 , 'PAC/' ,NULL) || DECODE(  race_white , 1 , 'WHT/' ,NULL) || DECODE(  race_multiple , 1 , 'MUL/' ,NULL) || DECODE(  race_other , 1 , 'OTH/' ,NULL) || DECODE(  race_unknown , 1 , 'UNK' ,NULL) race   from STD_DEATH_DOC std_dth, DOCUMENT_LOCATOR doc_locator, CODED_ETHNICITY e where  std_dth.DOCUMENT_ID = doc_locator.DOCUMENT_ID and  std_dth.DOCUMENT_ID = #{documentId}
 AND std_dth.ETHNICITY = e.ETHNICITY_CODE (+)

select std_casa.DOCUMENT_ID documentId, #{documentType}  as documentType, std_casa.FNAME firstName, std_casa.LNAME lastName, DOB_TEXT  dateOfBirth, std_casa.SSN ssn, e.ETHNICITY_DESCRIPTION ethnicity,  std_casa.PERSON_ZIP address, TO_CHAR(doc_locator.RECEIVED_DATE,'MM/DD/YYYY') recievedDate, DECODE( race_indian , 1 , 'IND/' ,NULL) || DECODE(  race_black , 1 , 'BLK/' ,NULL) || DECODE(  race_asian , 1 , 'ASI/' ,NULL) || DECODE(  race_pacific , 1 , 'PAC/' ,NULL) || DECODE(  race_white , 1 , 'WHT/' ,NULL) || DECODE(  race_multiple , 1 , 'MUL/' ,NULL) || DECODE(  race_other , 1 , 'OTH/' ,NULL) || DECODE(  race_unknown , 1 , 'UNK' ,NULL) race 
from STD_CASA_DOC std_casa, DOCUMENT_LOCATOR doc_locator, CODED_ETHNICITY e where  std_casa.DOCUMENT_ID = doc_locator.DOCUMENT_ID and  std_casa.DOCUMENT_ID = #{documentId} 
AND std_casa.ETHNICITY = e.ETHNICITY_CODE (+)

		 select med.DOCUMENT_ID documentId,  #{documentType}  as documentType, med.FNAME firstName, med.LNAME lastName, med.DOB_TEXT dateOfBirth, med.DOD_TEXT dateOfDeath, e.ETHNICITY_DESCRIPTION ethnicity, 
med.PERSON_ADDRESS || ', ' || med.PERSON_CITY || ', ' || med.PERSON_STATE || ', ' || med.PERSON_ZIP address, TO_CHAR(doc_locator.RECEIVED_DATE,'MM/DD/YYYY') recievedDate, providers.PROV_NAME as providerName, DECODE( race_indian , 1 , 'IND/' ,NULL) || DECODE(  race_black , 1 , 'BLK/' ,NULL) || DECODE(  race_asian , 1 , 'ASI/' ,NULL) || DECODE(  race_pacific , 1 , 'PAC/' ,NULL) || DECODE(  race_white , 1 , 'WHT/' ,NULL) || DECODE(  race_multiple , 1 , 'MUL/' ,NULL) || DECODE(  race_other , 1 , 'OTH/' ,NULL) || DECODE(  race_unknown , 1 , 'UNK' ,NULL) race   from STD_MEDICAID_DOC med, DOCUMENT_LOCATOR doc_locator, STD_MEDICAID_DOC_PROVIDERS providers, CODED_ETHNICITY e where  med.DOCUMENT_ID = doc_locator.DOCUMENT_ID and med.DOCUMENT_ID = providers.MEDICAID_DOC_ID(+) and  med.DOCUMENT_ID = #{documentId}
AND med.ETHNICITY = e.ETHNICITY_CODE (+)


